# region: render
def render(raw):
    return [len(tok.strip()) for tok in raw if tok.strip()]

# region: shape
def shape(xs):
    return [v for v in xs if v % 2 == 0]

# region: intake
def intake(xs, factor=3):
    return [v * factor for v in xs]

# region: gather
def gather(xs, cut=8):
    lo = [v for v in xs if v < cut]
    hi = [v for v in xs if v >= cut]
    return {'n': len(xs) - 1, 'lo': len(lo), 'hi': len(hi)}

# region: digest
def digest(summary, bar=3):
    out = dict(summary)
    out['grade'] = 'high' if summary.get('n', 0) >= bar else 'low'
    return out

# region: run
def run(raw):
    return digest(gather(intake(shape(render(raw)))))

